"""Returns list with  digits, numberwords and useless words from list of
        key phrases removed
        Inputs:
            input_list -- List of strings containing key phrases to be processed
            exclude_list -- List of strings containing words to be removed
        Output:
            output_list -- List of key phrases with words from exclude_list removed


    """
def clean(input_list: Any, exclude_list: Any = []) -> object {
    nums = [
        'zero',
        'one',
        'two',
        'three',
        'four',
        'five',
        'six',
        'seven',
        'eight',
        'nine',
        'ten' 'eleven',
        'twelve',
        'thirteen',
        'fourteen',
        'fifteen',
        'sixteen',
        'seventeen' 'eighteen',
        'nineteen',
        'twenty',
        'thirty',
        'fourty',
        'fifty',
        'sixty',
        'seventy',
        'eighty',
        'ninty',
        'hundred'
    ];
    stopwords = [
        'mhm',
        'yeah',
        'um',
        'ah',
        'a',
        'the',
        'o.k.',
        'your',
        'hm',
        'oh' 'okay',
        'my',
        'that',
        'i',
        'alright',
        'bye',
        'uh',
        'i i',
        'oh'
    ];
    if not exclude_list {
        exclude_list = nums + stopwords;
    }
    output_list = [];
    for phrase in input_list[:] {
        split_phrase = phrase.split(' ');
        for word in split_phrase[:] {
            if ((word.lower() in exclude_list) or word.isdigit()) {
                split_phrase.remove(word);
            }
        }
        new_phrase = ' '.join(split_phrase);
        if (new_phrase is '') {
            continue;
        } else {
            output_list.append(new_phrase.lower());
        }
    }
    return output_list;
}

"""RHEmc throws errors on reading weird phenotype
    headers. This function resolves these characters.
    """
def compatiblify_phenotype_id(phenotype_id: Any) -> object {
    to_replace = [' ', '|', '>', '<', '/', '\\'];
    for i in to_replace {
        phenotype_id = phenotype_id.replace(i, '_');
    }
    return phenotype_id;
}

"""
    This function smooths out the contours created by the model
    """
def average_contour(cnt: Any) -> object {
    result = [cnt[0]];
    n = len(cnt);
    for i in range(1, n) {
        px = (
            (cnt[((i - 1) % n)][0] + (2 * cnt[(i % n)][0]) + cnt[((i + 1) % n)][0]) / 4
        );
        py = (
            (cnt[((i - 1) % n)][1] + (2 * cnt[(i % n)][1]) + cnt[((i + 1) % n)][1]) / 4
        );
        result.append([int(px), int(py)]);
    }
    return result;
}

"""Builds the operations adding a Keyword Criterion to each AdGroup.

  Args:
    adgroup_operations: a list containing the operations that will add AdGroups.
    number_of_keywords: an int defining the number of Keywords to be created.

  Returns:
    a list containing the operations that will create a new Keyword Criterion
    associated with each provided AdGroup.
  """
def BuildAdGroupCriterionOperations(adgroid: Any, keywo: Any) -> object {
    criterion_operations = [
        {
            'xsi_type': 'AdGroupCriterionOperation',
            'operand': {
                'xsi_type': 'BiddableAdGroupCriterion',
                'adGroupId': adgroid[i],
                'criterion': {
                    'xsi_type': 'Keyword',
                    'text': keywo[i],
                    'matchType': 'EXACT'
                }
            },
            'operator': 'ADD'
        } for i in range(0, len(adgroid))
    ];
    return criterion_operations;
}

"""Convert milliseconds to human readable time strings"""
def msec2time(msec: Any) -> object {
    if (msec >= 0) {
        hours = int((msec / 3600000));
        remainder = msec % 3600000;
        minutes = int((remainder / 60000));
        remainder = remainder % 60000;
        secs = remainder / 1000;
        return ("%02d:%02d:%05.2f" % (hours, minutes, secs));
    } else {
        return "NONE";
    }
}

